pub fn yalign_x(n: Int) -> () {
    set(y_items(), kayak_rt::heap_cons(xa(n), get(y_items())))
}

pub fn ycall_x(l: Int) -> () {
    set(y_items(), kayak_rt::heap_cons(xj(y_call(), int_lit(0), l), get(y_items())))
}

// Data, placed before the code: 8 bytes an entry.
pub fn y_data() -> Ref<List<&'static XItem>> {
    kayak_rt::kept_constant!(ONCE: Ref<List<&'static XItem>>);
    once(&ONCE, || {
        kayak_rt::heap_new(nil::<&'static XItem>())
    })
}

pub fn yd_x(v: Int) -> () {
    set(y_data(), kayak_rt::heap_cons(xb((&x86::x86_le8)(v)), get(y_data())))
}

pub fn ydo_x(l: Int) -> () {
    set(y_data(), kayak_rt::heap_cons(xo(l), get(y_data())))
}

pub fn ydata_label_x(l: Int) -> () {
    set(y_data(), kayak_rt::heap_cons(xl(l), get(y_data())))
}

pub fn y_length(mut bs: List<Int>, mut n: Int) -> Int {
    loop {
        if null_p(bs) {
            return n;
        } else {
            (bs, n) = (cdr(bs), _plus(n, int_lit(1)));
            continue;
        }
    }
}

pub fn y_size(x: &'static XItem, at: Int) -> Int {
    let tagcase_ = x;
    match *tagcase_ {
        XItem::Xb(bs) => {
            y_length(bs, int_lit(0))
        }
        XItem::Xj(k, a, l) => {
            if (_eq(k, y_jmp()) || _eq(k, y_call())) {
                int_lit(5)
            } else if _eq(k, y_jcc()) {
                int_lit(6)
            } else {
                int_lit(7)
            }
        }
        XItem::Xo(l) => {
            int_lit(8)
        }
        XItem::Xa(z) => {
            modulo(_minus(int_lit(8), modulo(_plus(at, z), int_lit(8))), int_lit(8))
        }
        XItem::Xl(l) => {
            int_lit(0)
        }
    }
}

/// Each label's place, in bytes, in `ls`; how many bytes there are.
pub fn y_placed_x(mut xs: List<&'static XItem>, mut at: Int, mut ls: FlatArray<i64>) -> Int {
    loop {
        if null_p(xs) {
            return at;
        } else {
            let tagcase_ = car(xs);
            match *tagcase_ {
                XItem::Xl(l) => {
                    flatarray_set_i64_x(ls, int_to_i64(l), int_to_i64(at));
                    xs = cdr(xs);
                    continue;
                }
                _ => {
                    let x = tagcase_;
                    (xs, at) = (cdr(xs), _plus(at, y_size(x, at)));
                    continue;
                }
            }
        }
    }
}

/// Item `x`, at byte `at`: a jump by its label's distance from its end.
pub fn y_encoded(x: &'static XItem, at: Int, ls: FlatArray<i64>) -> List<Int> {
    let tagcase_ = x;
    match *tagcase_ {
        XItem::Xb(bs) => {
            bs
        }
        XItem::Xj(k, a, l) => {
            let d = _minus(r#where(ls, l), _plus(at, y_size(x, at)));
            if _eq(k, y_jmp()) {
                (&x86::x86_jmp)(d)
            } else if _eq(k, y_jcc()) {
                (&x86::x86_jcc)(a, d)
            } else if _eq(k, y_call()) {
                (&x86::x86_call)(d)
            } else {
                (&x86::x86_lea_rip)(a, d)
            }
        }
        XItem::Xo(l) => {
            (&x86::x86_le8)(r#where(ls, l))
        }
        XItem::Xa(z) => {
            (&x86::x86_nops)(y_size(x, at))
        }
        XItem::Xl(l) => {
            nil::<Int>()
        }
    }
}

