/// Given back unless `r`'s tag is `tag`.
pub fn ytag_in_x(r: Int, tag: Int) -> () {
    ymov_x(y13(), r);
    yalui_x(a_and(), y13(), int_lit(7));
    yalui_x(a_cmp(), y13(), tag);
    ygive_if_x(q_ne())
}

/// At least `n` values on the data stack (1 or 2), else give back.
pub fn yneed_x(n: Int) -> () {
    if _eq(n, int_lit(1)) {
        ycmp_st_x(y_dsp(), st_dsb());
        ygive_if_x(q_be())
    } else {
        yst_ld_x(y13(), st_dsb());
        yalui_x(a_add(), y13(), int_lit(8));
        yalu_x(a_cmp(), y_dsp(), y13());
        ygive_if_x(q_be())
    }
}

