    yst_x(y_rsp(), int_lit(0), y_cur());
    yst_x(y_rsp(), int_lit(8), y13());
    yst_x(y_rsp(), int_lit(16), y14());
    yst_x(y_rsp(), int_lit(24), y_clo());
